coding.solution:
def mask(record):
    out = dict(record)
    if 'email' in out:
        out['email'] = f"user{record['id']}@example.test"
    if 'phone' in out:
        digits = ''.join(ch for ch in str(out['phone']) if ch.isdigit())
        out['phone'] = '*' * max(len(digits) - 2, 0) + digits[-2:]
    return out
